-- The Alpha POC database is intentionally not referenced by this migration.
CREATE DATABASE IF NOT EXISTS ONE_HEALTH_LYME_GAP_ATLAS_DEV;
USE DATABASE ONE_HEALTH_LYME_GAP_ATLAS_DEV;
CREATE SCHEMA IF NOT EXISTS GOVERNANCE;
CREATE SCHEMA IF NOT EXISTS RAW;
CREATE SCHEMA IF NOT EXISTS STAGING;
CREATE SCHEMA IF NOT EXISTS CONFORMED;
CREATE SCHEMA IF NOT EXISTS ANALYTICS;
CREATE SCHEMA IF NOT EXISTS FEATURE_STORE;
CREATE TABLE IF NOT EXISTS GOVERNANCE.SCHEMA_MIGRATIONS (version VARCHAR PRIMARY KEY, filename VARCHAR NOT NULL, sha256 VARCHAR(64) NOT NULL, applied_at TIMESTAMP_LTZ NOT NULL DEFAULT CURRENT_TIMESTAMP(), deployment_commit VARCHAR, applied_by VARCHAR);
CREATE TABLE IF NOT EXISTS GOVERNANCE.CATALOG_DATASETS (catalog_dataset_id VARCHAR PRIMARY KEY, dataset_key VARCHAR NOT NULL, catalog_name VARCHAR NOT NULL, catalog_record_id VARCHAR, metadata_payload VARIANT, metadata_sha256 VARCHAR(64), discovered_at TIMESTAMP_LTZ NOT NULL, is_current BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.CATALOG_RESOURCES (catalog_resource_id VARCHAR PRIMARY KEY, catalog_dataset_id VARCHAR NOT NULL, resource_key VARCHAR NOT NULL, resource_type VARCHAR NOT NULL, resource_url VARCHAR, canonical_source_url VARCHAR, api_dataset_id VARCHAR, resource_payload VARIANT, registered_at TIMESTAMP_LTZ NOT NULL, is_active BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.SOURCE_ACCESS_PROFILES (source_access_profile_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, profile_version NUMBER NOT NULL, connector_name VARCHAR NOT NULL, endpoint_template VARCHAR, deterministic_order_clause VARCHAR, incremental_strategy VARCHAR, configuration_sha256 VARCHAR(64), effective_from TIMESTAMP_LTZ NOT NULL, effective_to TIMESTAMP_LTZ);
CREATE TABLE IF NOT EXISTS GOVERNANCE.SOURCE_DOCUMENT_SNAPSHOTS (source_document_snapshot_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, document_type VARCHAR NOT NULL, document_url VARCHAR, artifact_id VARCHAR, content_sha256 VARCHAR(64), retrieved_at TIMESTAMP_LTZ NOT NULL, is_material_change BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.DATASET_QUALITY_ASSESSMENTS (dataset_quality_assessment_id VARCHAR PRIMARY KEY, resource_key VARCHAR, assessment_status VARCHAR NOT NULL, relevance_score NUMBER(5,2), joinability_score NUMBER(5,2), accessibility_score NUMBER(5,2), documentation_score NUMBER(5,2), quality_score NUMBER(5,2), overall_score NUMBER(5,2), recommendation VARCHAR, limitations VARCHAR, assessed_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.INGESTION_RUNS (ingestion_run_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, source_access_profile_id VARCHAR, run_mode VARCHAR NOT NULL, trigger_type VARCHAR NOT NULL, status VARCHAR NOT NULL, code_version VARCHAR, config_sha256 VARCHAR(64), started_at TIMESTAMP_LTZ NOT NULL, completed_at TIMESTAMP_LTZ, error_classification VARCHAR, redacted_error VARCHAR);
CREATE TABLE IF NOT EXISTS GOVERNANCE.INGESTION_REQUESTS (ingestion_request_id VARCHAR PRIMARY KEY, ingestion_run_id VARCHAR NOT NULL, request_sequence NUMBER NOT NULL, request_purpose VARCHAR NOT NULL, endpoint VARCHAR NOT NULL, redacted_request VARIANT, status_code NUMBER, response_sha256 VARCHAR(64), retrieved_row_count NUMBER, created_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.RAW_ARTIFACTS (artifact_id VARCHAR PRIMARY KEY, ingestion_run_id VARCHAR NOT NULL, ingestion_request_id VARCHAR, artifact_uri VARCHAR NOT NULL, artifact_type VARCHAR NOT NULL, media_type VARCHAR, byte_count NUMBER NOT NULL, sha256 VARCHAR(64) NOT NULL, retention_class VARCHAR NOT NULL DEFAULT 'PUBLIC_SEVEN_YEAR', created_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.SCHEMA_SNAPSHOTS (schema_snapshot_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, artifact_id VARCHAR, schema_fingerprint VARCHAR(64) NOT NULL, schema_payload VARIANT, retrieved_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.SCHEMA_CHANGE_EVENTS (schema_change_event_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, prior_schema_snapshot_id VARCHAR, new_schema_snapshot_id VARCHAR NOT NULL, compatibility_outcome VARCHAR NOT NULL, detected_at TIMESTAMP_LTZ NOT NULL, justification VARCHAR);
CREATE TABLE IF NOT EXISTS GOVERNANCE.DATA_QUALITY_RESULTS (data_quality_result_id VARCHAR PRIMARY KEY, ingestion_run_id VARCHAR NOT NULL, rule_id VARCHAR NOT NULL, severity VARCHAR NOT NULL, status VARCHAR NOT NULL, expected_value VARIANT, observed_value VARIANT, created_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.MANUAL_REVIEW_DECISIONS (manual_review_decision_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, decision VARCHAR NOT NULL, rationale VARCHAR NOT NULL, conditions VARIANT, reviewer_username VARCHAR NOT NULL, supersedes_decision_id VARCHAR, decided_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.DATA_SOURCE_VERSIONS (data_source_version_id VARCHAR PRIMARY KEY, resource_key VARCHAR NOT NULL, ingestion_run_id VARCHAR, artifact_id VARCHAR, schema_snapshot_id VARCHAR, status VARCHAR NOT NULL, approved_decision_id VARCHAR, created_at TIMESTAMP_LTZ NOT NULL, retired_at TIMESTAMP_LTZ);
CREATE TABLE IF NOT EXISTS GOVERNANCE.TRANSFORMATION_RUNS (transformation_run_id VARCHAR PRIMARY KEY, transformation_name VARCHAR NOT NULL, code_version VARCHAR, input_source_versions VARIANT NOT NULL, target_relation VARCHAR NOT NULL, status VARCHAR NOT NULL, started_at TIMESTAMP_LTZ NOT NULL, completed_at TIMESTAMP_LTZ);
CREATE TABLE IF NOT EXISTS GOVERNANCE.LINEAGE_EDGES (lineage_edge_id VARCHAR PRIMARY KEY, transformation_run_id VARCHAR NOT NULL, input_object VARCHAR NOT NULL, output_object VARCHAR NOT NULL, geography_semantics VARCHAR, temporal_window VARCHAR, aggregation_method VARCHAR, created_at TIMESTAMP_LTZ NOT NULL);
CREATE TABLE IF NOT EXISTS GOVERNANCE.RESOURCE_LOCKS (resource_key VARCHAR PRIMARY KEY, owner_run_id VARCHAR NOT NULL, lease_expires_at TIMESTAMP_LTZ NOT NULL, acquired_at TIMESTAMP_LTZ NOT NULL);
